import XCTest
import Foundation
import DemoFirstScreenCore
import ReadOnlyScanner
@testable import FolderSnapshotAdapter

final class FolderSnapshotTests:XCTestCase {
    func scan(_ dirs:[String:Int64]=[:],files:[String:Int64]=[:])->SpaceSnapshot {
        var entries=[String:DirectoryEntry]();var inode:UInt64=1
        func put(_ path:String,_ kind:EntryKind,_ bytes:Int64){entries[path]=DirectoryEntry(relativePath:path,kind:kind,logicalSize:bytes,allocatedSize:nil,modifiedAt:nil,device:1,inode:inode,countsTowardTotal:false,hardLinkNote:nil);inode+=1}
        put(".",.directory,0)
        for name in dirs.keys.sorted(){put(name,.directory,0);if dirs[name]!>0 {put(name+"/file",.regularFile,dirs[name]!)}}
        for name in files.keys.sorted(){put(name,.regularFile,files[name]!)}
        return SpaceSnapshot(selectedPath:"/injected-only",rootPath:"/injected-only",rootResolutionNote:nil,breadthWarning:nil,capturedAt:Date(timeIntervalSince1970:100),entriesByPath:entries,issues:[],completed:true,cancelled:false,failureReason:nil,totalLogicalBytes:999999,totalAllocatedBytes:888,regularFileCount:0,directoryCount:dirs.count,symbolicLinkCount:0,hardLinkAliasCount:0)
    }
    func result(_ dirs:[String:Int64]=[:],files:[String:Int64]=[:])->FolderResult {FolderAdapter.adapt(scan(dirs,files:files))}
    func testInitialStateNeutralNoData(){let s=FolderReadState();XCTAssertFalse(s.reading);XCTAssertNil(s.root);XCTAssertNil(s.visible);XCTAssertTrue(s.snapshot.items.isEmpty);XCTAssertFalse(ChartabilityGate.evaluate(s.snapshot).isChartable)}
    func testCompleteEmptyDifferentFromRootFailure(){XCTAssertEqual(result().outcome,.empty);var s=scan();s.entriesByPath=[:];s.completed=false;s.failureReason="denied";let r=FolderAdapter.adapt(s);XCTAssertEqual(r.outcome,.failed);XCTAssertFalse(ChartabilityGate.evaluate(r.snapshot).isChartable);XCTAssertTrue(r.snapshot.items.isEmpty)}
    func testOneAndUpToFiveNoPadding(){for n in 1...5{let r=result(Dictionary(uniqueKeysWithValues:(1...n).map{("D\($0)",Int64($0))}));XCTAssertEqual(r.snapshot.items.count,n);XCTAssertEqual(ChartabilityGate.evaluate(r.snapshot).sectors.count,n)}}
    func testMoreThanFiveDirectoriesTopFourOther(){let r=result(["a":1,"b":2,"c":3,"d":4,"e":5,"f":6]);XCTAssertEqual(r.snapshot.items.count,5);XCTAssertEqual(r.snapshot.items.last?.id,"aggregate:other");XCTAssertEqual(r.snapshot.items.last?.bytes,3);XCTAssertEqual(r.snapshot.items.first?.name,"f")}
    func testExactlyFiveAndDirectFileReservesOther(){let r=result(["a":1,"b":2,"c":3,"d":4,"e":5],files:["root":10]);XCTAssertEqual(r.snapshot.items.count,5);XCTAssertEqual(r.snapshot.items.last?.bytes,11);XCTAssertFalse(r.snapshot.items.contains{$0.name=="a"})}
    func testOnlyFilesOneAggregate(){let r=result(files:["a":7,"b":9]);XCTAssertEqual(r.snapshot.items.map(\.id),["aggregate:other"]);XCTAssertEqual(r.snapshot.items[0].bytes,16)}
    func testZeroAggregateNotForced(){let r=result(["a":5],files:["zero":0]);XCTAssertEqual(r.snapshot.items.count,1);XCTAssertFalse(r.snapshot.items.contains{$0.id=="aggregate:other"})}
    func testRealOtherDirectoryCannotCollideWithAggregate(){let r=result(["其他项目":5],files:["x":7]);XCTAssertEqual(Set(r.snapshot.items.map(\.id)).count,2);XCTAssertEqual(r.snapshot.items.map(\.name),["其他项目","其他项目"])}
    func testStableHardlinkOwnershipBeforeBucketSorting(){var s=scan(["A":4,"B":400],files:["z":4]);let a=s.entriesByPath["A/file"]!;s.entriesByPath["B/file"]!.device=a.device;s.entriesByPath["B/file"]!.inode=a.inode;s.entriesByPath["B/file"]!.logicalSize=4;s.entriesByPath["z"]!.device=a.device;s.entriesByPath["z"]!.inode=a.inode;let r=FolderAdapter.adapt(s);XCTAssertEqual(r.snapshot.items.first{$0.name=="A"}?.bytes,4);XCTAssertEqual(r.snapshot.items.first{$0.name=="B"}?.bytes,0);XCTAssertFalse(r.snapshot.items.contains{$0.id=="aggregate:other"});XCTAssertEqual(r.snapshot.folderLogicalProof?.bucketTotal,4)}
    func testEnumerationFlagsAndInsertionOrderIgnored(){var s=scan(["A":10,"B":20]);let a=FolderAdapter.adapt(s);for k in s.entriesByPath.keys {s.entriesByPath[k]!.countsTowardTotal.toggle()};s.entriesByPath=Dictionary(uniqueKeysWithValues:s.entriesByPath.sorted{$0.key>$1.key});let b=FolderAdapter.adapt(s);XCTAssertEqual(a.snapshot.items,b.snapshot.items)}
    func testPartialDoesNotDrawKnownSubset(){var s=scan(["A":10,"B":20]);s.issues=[ScanIssue(path:"B",message:"permission injected")];let r=FolderAdapter.adapt(s);XCTAssertEqual(r.outcome,.partial);XCTAssertEqual(r.snapshot.items.count,2);XCTAssertFalse(ChartabilityGate.evaluate(r.snapshot).isChartable);XCTAssertTrue(r.snapshot.items.allSatisfy{$0.readStatus == .partial})}
    func testSymlinkAndMountSkipArePartial(){var s=scan(files:["x":3]);s.entriesByPath["x"]!.kind = .symbolicLink;XCTAssertEqual(FolderAdapter.adapt(s).outcome,.partial);s.entriesByPath["x"]!.kind = .regularFile;s.entriesByPath["x"]!.device=999;XCTAssertEqual(FolderAdapter.adapt(s).outcome,.partial)}
    func testLogicalProofNeverClaimsPhysicalAPFS(){let r=result(["A":100]);XCTAssertFalse(r.snapshot.apfsRootDataDedupVerified);XCTAssertTrue(ChartabilityGate.evaluate(r.snapshot).isChartable);var x=r.snapshot;x.caliber = .allocated;XCTAssertFalse(ChartabilityGate.evaluate(x).isChartable);x=r.snapshot;x.apfsRootDataDedupVerified=true;XCTAssertFalse(ChartabilityGate.evaluate(x).isChartable);x=r.snapshot;x.folderLogicalProof!.bucketTotal+=1;XCTAssertFalse(ChartabilityGate.evaluate(x).isChartable)}
    func testSameScopeCancelKeepsSuccessfulTimeAndStale(){var state=FolderReadState();let r=result(["A":2]);let g=state.begin(root:r.root);XCTAssertTrue(state.finish(r,generation:g,root:r.root));_=state.begin(root:r.root);state.cancel();XCTAssertTrue(state.stale);XCTAssertEqual(state.visible?.snapshot.endedAt,r.snapshot.endedAt)}
    func testDifferentScopeCancelCannotBorrowOld(){var state=FolderReadState();let r=result(["A":2]);let g=state.begin(root:r.root);_=state.finish(r,generation:g,root:r.root);_=state.begin(root:"/other-injected");state.cancel();XCTAssertNil(state.visible);XCTAssertFalse(state.stale)}
    func testOldSameAndDifferentScopeResultsNeverOverwrite(){var state=FolderReadState();let r=result(["A":2]);let g=state.begin(root:r.root);_=state.begin(root:r.root);XCTAssertFalse(state.finish(r,generation:g,root:r.root));let old=state.generation;_=state.begin(root:"/other-injected");XCTAssertFalse(state.finish(r,generation:old,root:r.root));state.cancel();XCTAssertFalse(state.finish(r,generation:state.generation,root:r.root))}
    func testProgressCountNotPercentageAndOldProgressIgnored(){var state=FolderReadState();let g=state.begin(root:"/fixture");state.progress(72,generation:g,root:"/fixture");XCTAssertEqual(state.visited,72);state.cancel();state.progress(999,generation:g,root:"/fixture");XCTAssertEqual(state.visited,72);XCTAssertFalse(state.status.contains("%"))}
    func testNeutralAndPartialDefaultForwardLargestPositiveWhenComplete(){for r in [result(),{var s=scan(["A":2]);s.issues=[ScanIssue(path:"A",message:"partial")];return FolderAdapter.adapt(s)}()]{let f=FramePresentation.make(session:InteractionSession(snapshot:r.snapshot),motion:.reduced,pointerInsideWindow:false);XCTAssertEqual(f.eye.resolvedTarget,SafeGaze.center)};let r=result(["A":2,"B":8]);let f=FramePresentation.make(session:InteractionSession(snapshot:r.snapshot),motion:.reduced,pointerInsideWindow:false);XCTAssertEqual(f.eye.defaultTargetID,"directory:B")}
    func testPanelLeaseAndFalseExplicitStartBalance(){var starts=0,stops=0;do{let s=SessionScopeLease(implicitPanelAccess:true,start:{starts+=1;return false},stop:{stops+=1});s.close();s.close()};XCTAssertEqual(starts,0);XCTAssertEqual(stops,1);do{let s=SessionScopeLease(implicitPanelAccess:false,start:{starts+=1;return false},stop:{stops+=1});s.close()};XCTAssertEqual(starts,1);XCTAssertEqual(stops,1);do{let s=SessionScopeLease(implicitPanelAccess:false,start:{true},stop:{stops+=1});s.close()};XCTAssertEqual(stops,2)}
    func fixture()throws->URL {let parent=ProcessInfo.processInfo.environment["FS_TEST_FIXTURE_PARENT"].map{URL(fileURLWithPath:$0)} ?? FileManager.default.temporaryDirectory.appendingPathComponent("FSMonitor-OwnFixtures");let url=parent.appendingPathComponent(UUID().uuidString);try FileManager.default.createDirectory(at:url,withIntermediateDirectories:true);return url}
    func testActualScannerOwnFixtureHardlinkAndLogicalSize()throws{let u=try fixture();for n in ["A","B"]{try FileManager.default.createDirectory(at:u.appendingPathComponent(n),withIntermediateDirectories:true)};let file=u.appendingPathComponent("B/file");try Data(repeating:7,count:123).write(to:file);try FileManager.default.linkItem(at:file,to:u.appendingPathComponent("A/link"));let scan=DirectoryScanner.scan(root:u,cancellation:ScanCancellation());let r=FolderAdapter.adapt(scan);XCTAssertEqual(r.snapshot.folderLogicalProof?.bucketTotal,123);XCTAssertEqual(r.snapshot.items.first{$0.name=="A"}?.bytes,123);XCTAssertEqual(r.snapshot.items.first{$0.name=="B"}?.bytes,0);XCTAssertTrue(r.isComplete)}
    func testActualScannerOwnFixtureSymlinkNotFollowed()throws{let u=try fixture();try Data(repeating:1,count:17).write(to:u.appendingPathComponent("file"));try FileManager.default.createSymbolicLink(at:u.appendingPathComponent("link"),withDestinationURL:u.appendingPathComponent("file"));let r=FolderAdapter.adapt(DirectoryScanner.scan(root:u,cancellation:ScanCancellation()));XCTAssertEqual(r.outcome,.partial);XCTAssertEqual(r.snapshot.items.first?.bytes,17)}
    func testActualScannerOwnFixturePreCancelledAndEmpty()throws{let u=try fixture();let c=ScanCancellation();c.cancel();XCTAssertEqual(FolderAdapter.adapt(DirectoryScanner.scan(root:u,cancellation:c)).outcome,.cancelled);XCTAssertEqual(FolderAdapter.adapt(DirectoryScanner.scan(root:u,cancellation:ScanCancellation())).outcome,.empty)}
}
